raw.css:
:root {
  --color-primary: #8b5a3c;
  --color-primary-dark: #5c3a24;
  --color-accent: #d4a574;
  --color-accent-light: #f5ead6;
  --color-text: #2c2c2c;
  --color-text-light: #f9f7f4;
  --color-bg: #faf8f5;
  --color-bg-card: #ffffff;
  --color-border: #e8dccf;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-xxl: 4rem;
  --shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  --shadow-hover: 0 4px 16px rgba(0, 0, 0, 0.15);
}

* {
  box-sizing: border-box;
}

html {
  font-size: 16px;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  color: var(--color-primary-dark);
  margin: var(--spacing-md) 0 var(--spacing-sm) 0;
  line-height: 1.3;
}

h1 {
  font-size: 2.5rem;
  margin-top: 0;
}

h2 {
  font-size: 2rem;
}

h3 {
  font-size: 1.5rem;
}

p {
  margin: var(--spacing-sm) 0;
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: border-color 0.2s ease;
}

a:hover {
  border-bottom-color: var(--color-primary-dark);
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

header {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-md);
}

.logo {
  font-family: "Brush Script MT", "Segoe Script", cursive;
  font-size: 1.8rem;
  font-weight: 400;
  color: var(--color-accent);
  text-decoration: none;
  border: none;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
  letter-spacing: 0.05em;
}

.logo:hover {
  border: none;
  opacity: 0.9;
}

.logo:focus {
  outline: 2px solid var(--color-accent-light);
  outline-offset: 2px;
  border: none;
}

header nav {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
}

header nav a {
  color: var(--color-text-light);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-bottom: 2px solid transparent;
  transition: border-color 0.2s ease;
}

header nav a:hover {
  border-bottom-color: var(--color-accent);
}

header nav a:focus {
  outline: 2px solid var(--color-accent-light);
  outline-offset: 2px;
}

footer {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  padding: var(--spacing-lg) var(--spacing-md);
  margin-top: var(--spacing-xxl);
  text-align: center;
}

footer a {
  color: var(--color-accent-light);
  border-bottom-color: var(--color-accent-light);
}

footer a:hover {
  border-bottom-color: var(--color-accent);
}

footer p {
  margin: var(--spacing-xs) 0;
  font-size: 0.95rem;
}

button, .btn {
  display: inline-block;
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-lg);
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  border: 2px solid var(--color-primary-dark);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  text-decoration: none;
  text-align: center;
}

button:hover, .btn:hover {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
  color: var(--color-text);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: scale(0.98);
}

.card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: var(--shadow);
  transition: box-shadow 0.2s ease;
}

.card:hover {
  box-shadow: var(--shadow-hover);
}

.grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  max-width: 600px;
}

label {
  font-weight: 600;
  color: var(--color-primary-dark);
  display: block;
  margin-bottom: var(--spacing-xs);
}

input, textarea, select {
  min-height: 44px;
  padding: var(--spacing-sm);
  border: 2px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: var(--color-bg-card);
  transition: border-color 0.2s ease;
}

input:focus, textarea:focus, select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px var(--color-accent-light);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

@media (max-width: 600px) {
  :root {
    font-size: 14px;
  }

  h1 {
    font-size: 1.8rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.2rem;
  }

  .logo {
    font-size: 1.4rem;
  }

  header .container {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-sm);
  }

  header nav {
    flex-direction: column;
    gap: var(--spacing-xs);
    width: 100%;
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .card {
    padding: var(--spacing-md);
  }
}

@media (min-width: 601px) {
  header .container {
    flex-wrap: nowrap;
  }

  header nav {
    margin-left: auto;
  }

  .container {
    padding: 0 var(--spacing-lg);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-text-light);
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
}

.index-hero h1 {
  color: var(--color-text-light);
  margin-top: 0;
}

.index-hero-tagline {
  font-size: 1.2rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.index-hero .btn {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
  color: var(--color-text);
}

.index-hero .btn:hover {
  background-color: var(--color-accent-light);
  border-color: var(--color-accent-light);
}

.index-featured {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.index-featured-content {
  display: flex;
  gap: var(--spacing-lg);
  align-items: flex-start;
  margin-top: var(--spacing-lg);
}

.index-book-cover {
  flex-shrink: 0;
}

.index-book-cover img {
  width: 250px;
  height: 375px;
  object-fit: cover;
  border-radius: 8px;
  box-shadow: var(--shadow-hover);
}

.index-book-info {
  flex: 1;
}

.index-book-info h3 {
  margin-top: 0;
  font-size: 2rem;
}

.index-book-author {
  font-size: 1.1rem;
  color: var(--color-primary);
  font-style: italic;
  margin-bottom: var(--spacing-md);
}

.index-book-info p {
  margin-bottom: var(--spacing-md);
}

.index-why {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xxl) var(--spacing-md);
}

.index-why h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.index-cta {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
}

.index-cta h2 {
  color: var(--color-text-light);
}

.index-cta p {
  font-size: 1.1rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.index-cta .btn {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
  color: var(--color-text);
}

.index-cta .btn:hover {
  background-color: var(--color-accent-light);
  border-color: var(--color-accent-light);
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .index-hero-tagline {
    font-size: 1rem;
  }

  .index-featured {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .index-featured-content {
    flex-direction: column;
    align-items: center;
    gap: var(--spacing-md);
  }

  .index-book-cover img {
    width: 200px;
    height: 300px;
  }

  .index-book-info {
    text-align: center;
  }

  .index-book-info h3 {
    font-size: 1.5rem;
  }

  .index-why {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .index-why h2 {
    margin-bottom: var(--spacing-lg);
  }

  .index-cta {
    padding: var(--spacing-xl) var(--spacing-md);
  }
}

@media (min-width: 601px) {
  .index-hero .container {
    max-width: 900px;
  }
}

.current-book-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-text-light);
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
}

.current-book-hero h1 {
  color: var(--color-text-light);
  margin-top: 0;
}

.current-book-subtitle {
  font-size: 1.1rem;
  color: var(--color-accent-light);
  margin: var(--spacing-md) 0 0 0;
}

.current-book-main {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.current-book-grid {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

.current-book-cover {
  flex-shrink: 0;
}

.current-book-cover img {
  width: 100%;
  height: auto;
  border-radius: 8px;
  box-shadow: var(--shadow-hover);
}

.current-book-details h2 {
  margin-top: 0;
}

.current-book-author {
  font-size: 1.2rem;
  color: var(--color-primary);
  font-style: italic;
  margin: 0 0 var(--spacing-lg) 0;
}

.current-book-info {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-lg);
  margin: var(--spacing-lg) 0;
  padding: var(--spacing-lg);
  background-color: var(--color-accent-light);
  border-radius: 6px;
}

.current-book-meta {
  flex: 1;
  min-width: 150px;
}

.current-book-meta strong {
  color: var(--color-primary-dark);
  display: block;
  margin-bottom: var(--spacing-xs);
}

.current-book-discussion {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xxl) var(--spacing-md);
}

.current-book-discussion h2 {
  text-align: center;
  margin-top: 0;
}

.current-book-prompts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.current-book-prompt-card {
  background-color: var(--color-bg-card);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border-left: 4px solid var(--color-primary-dark);
  box-shadow: var(--shadow);
}

.current-book-prompt-card h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.current-book-meeting {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.current-book-meeting h2 {
  text-align: center;
}

.current-book-meeting-card {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-text-light);
  padding: var(--spacing-xl);
  border-radius: 8px;
  max-width: 600px;
  margin: var(--spacing-lg) auto;
}

.current-book-meeting-card h3 {
  color: var(--color-accent-light);
  margin-top: 0;
}

.current-book-meeting-card p {
  color: var(--color-text-light);
}

.current-book-meeting-note {
  background-color: rgba(255, 255, 255, 0.1);
  padding: var(--spacing-md);
  border-radius: 6px;
  margin: var(--spacing-lg) 0;
  border-left: 3px solid var(--color-accent-light);
}

.current-book-meeting-card .btn {
  margin-top: var(--spacing-md);
  background-color: var(--color-accent);
  border-color: var(--color-accent);
  color: var(--color-text);
}

.current-book-meeting-card .btn:hover {
  background-color: var(--color-accent-light);
  border-color: var(--color-accent-light);
}

.current-book-about-choice {
  background-color: var(--color-bg-card);
  padding: var(--spacing-lg) var(--spacing-md);
  border-top: 2px solid var(--color-border);
}

@media (max-width: 600px) {
  .current-book-hero {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .current-book-main {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .current-book-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .current-book-cover {
    max-width: 250px;
    margin: 0 auto;
  }

  .current-book-info {
    flex-direction: column;
    gap: var(--spacing-md);
  }

  .current-book-meta {
    min-width: auto;
  }

  .current-book-discussion {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .current-book-prompts {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .current-book-meeting {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .current-book-meeting-card {
    padding: var(--spacing-lg);
    margin: var(--spacing-md) 0;
  }

  .current-book-about-choice {
    padding: var(--spacing-lg) var(--spacing-md);
  }
}

@media (min-width: 601px) {
  .current-book-main {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .current-book-discussion {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .current-book-meeting {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .current-book-about-choice {
    padding: var(--spacing-lg) var(--spacing-lg);
  }
}

.meetings-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-text-light);
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
}

.meetings-hero h1 {
  color: var(--color-text-light);
  margin-top: var(--spacing-lg);
}

.meetings-hero p {
  font-size: 1.1rem;
  opacity: 0.95;
}

.meetings-list {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.meetings-timeline {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
  position: relative;
  padding-left: var(--spacing-lg);
}

.meetings-timeline::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: linear-gradient(180deg, var(--color-primary-dark) 0%, var(--color-accent) 100%);
  border-radius: 2px;
}

.meetings-card {
  background-color: var(--color-bg-card);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: var(--shadow);
  transition: all 0.3s ease;
  position: relative;
  margin-left: var(--spacing-md);
}

.meetings-card::before {
  content: '';
  position: absolute;
  left: -32px;
  top: 24px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: var(--color-accent);
  border: 3px solid var(--color-primary-dark);
}

.meetings-card:hover {
  box-shadow: var(--shadow-hover);
  border-color: var(--color-accent);
  transform: translateX(4px);
}

.meetings-card-header {
  margin-bottom: var(--spacing-md);
}

.meetings-card-header h3 {
  margin: 0 0 var(--spacing-xs) 0;
  color: var(--color-primary-dark);
}

.meetings-date {
  font-size: 0.95rem;
  color: var(--color-primary);
  font-weight: 600;
  margin: 0;
}

.meetings-author {
  font-size: 1rem;
  color: var(--color-primary);
  margin: var(--spacing-xs) 0 var(--spacing-md) 0;
}

.meetings-summary {
  color: var(--color-text);
  margin-bottom: var(--spacing-md);
  line-height: 1.6;
}

.meetings-details {
  background-color: var(--color-accent-light);
  padding: var(--spacing-md);
  border-radius: 6px;
  border-left: 4px solid var(--color-primary-dark);
}

.meetings-details p {
  margin: var(--spacing-xs) 0;
  font-size: 0.95rem;
}

.meetings-quote {
  font-style: italic;
  color: var(--color-primary-dark);
  margin: var(--spacing-sm) 0 0 0;
  padding-left: var(--spacing-md);
  border-left: 3px solid var(--color-primary-dark);
  line-height: 1.6;
}

.meetings-stats {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xxl) var(--spacing-md);
}

.meetings-stats h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-lg);
}

.stat-card {
  background-color: var(--color-bg-card);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  text-align: center;
  box-shadow: var(--shadow);
  transition: transform 0.3s ease;
}

.stat-card:hover {
  transform: translateY(-4px);
}

.stat-number {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin: 0;
  line-height: 1;
}

.stat-label {
  font-size: 0.95rem;
  color: var(--color-primary);
  font-weight: 600;
  margin: var(--spacing-sm) 0 0 0;
}

.meetings-join-cta {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-text-light);
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
}

.meetings-join-cta h2 {
  color: var(--color-text-light);
}

.meetings-join-cta p {
  font-size: 1.05rem;
  opacity: 0.95;
  margin-bottom: var(--spacing-lg);
}

@media (max-width: 600px) {
  .meetings-timeline {
    padding-left: var(--spacing-md);
  }

  .meetings-timeline::before {
    left: -8px;
  }

  .meetings-card {
    margin-left: 12px;
  }

  .meetings-card::before {
    left: -24px;
    width: 12px;
    height: 12px;
    top: 20px;
  }

  .meetings-list {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .meetings-stats {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--spacing-md);
  }

  .stat-number {
    font-size: 2rem;
  }

  .meetings-join-cta {
    padding: var(--spacing-lg) var(--spacing-sm);
  }
}

@media (min-width: 601px) {
  .meetings-timeline {
    padding-left: var(--spacing-xl);
  }

  .meetings-timeline::before {
    left: -12px;
  }

  .meetings-card {
    margin-left: var(--spacing-xl);
  }

  .meetings-card::before {
    left: -28px;
  }
}

.join-hero {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xl) var(--spacing-md);
}

.join-intro {
  font-size: 1.1rem;
  max-width: 700px;
  margin-top: var(--spacing-md);
  color: var(--color-text);
}

.join-benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.join-benefit-card {
  background-color: var(--color-bg-card);
  border: 2px solid var(--color-accent);
  border-radius: 8px;
  padding: var(--spacing-lg);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.join-benefit-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.join-benefit-card h3 {
